  var FPS = 18;
  var el = document.getElementById("horse-anim");
  if (!el) return console.warn("horse-anim: no element with id \"horse-anim\" found");
  var fps = Number(el.dataset.fps) || FPS;
  var i = 0, last = 0;
  var reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  el.textContent = FRAMES[0];
  if (reduced) return;                      // static frame for reduced-motion users
  function tick(now) {
    if (now - last >= 1000 / fps) {
      last = now;
      i = (i + 1) % FRAMES.length;
      el.textContent = FRAMES[i];
    }
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
